<?= $this->include('layouts/header') ?><div class="page-head"><div><div class="page-kicker">Report</div><h1 class="page-title">Security report</h1><p class="page-subtitle">Trace every incoming paper from guard capture to inventory transaction.</p></div><div class="head-actions"><a class="btn" href="<?=site_url('reports')?>">← Reports</a><a class="btn primary" href="<?=site_url('reports/export/SECURITY')?>">Export CSV</a></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Date/time</th><th>Guard</th><th>Document</th><th>OCR</th><th>Supplier</th><th>Reference</th><th>Transaction</th><th>Verified</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8"><div class="empty"><strong>No security records</strong>Incoming entries will appear here.</div></td></tr><?php else: foreach($rows as $r): ?><tr><td><?=esc($r['created_at'])?></td><td><?=esc($r['guard_name'])?></td><td><?=esc($r['original_filename']??'Manual')?></td><td><span class="badge <?=$r['ocr_status']==='completed'?'success':'warning'?>"><?=esc($r['ocr_status'])?></span></td><td><?=esc($r['party_name']??'—')?></td><td class="mono"><?=esc($r['reference_no']??'—')?></td><td class="mono"><?=esc($r['transaction_no']??'—')?></td><td><span class="badge <?=$r['verified']?'success':'warning'?>"><?=$r['verified']?'Yes':'No'?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></div><?= $this->include('layouts/footer') ?>